      if (key !== null) return false;
      key = p.key.type === "Identifier" ? p.key.name : p.key.value;
      child = p.parent;
      p = child.parent;
      continue;
    }
    if (p.type === "CallExpression" && p.arguments.includes(child)) {
      const callee = p.callee.type === "Identifier" ? p.callee.name : null;
